components.css:
.ds-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; border: 1px solid var(--blue, #173F8A); border-radius: 4px; padding: 9px 17px; background: var(--blue, #173F8A); color: var(--white, #fff); font: 500 14px/1.6 'Noto Sans TC', sans-serif; text-decoration: none; cursor: pointer; touch-action: manipulation; }
.ds-primary:hover:enabled { background: #102F6B; }
.ds-primary:disabled { cursor: not-allowed; color: var(--secondary, #46546E); background: var(--ground, #EEF2F6); border-color: var(--rule, #C9D3DF); }
.ds-primary:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-secondary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; border: 1px solid var(--blue, #173F8A); border-radius: 4px; padding: 9px 17px; background: var(--white, #fff); color: var(--blue, #173F8A); font: 500 14px/1.6 'Noto Sans TC', sans-serif; text-decoration: none; cursor: pointer; touch-action: manipulation; }
.ds-secondary:hover:enabled { background: var(--ground, #EEF2F6); }
.ds-secondary:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-cancel-isolation { display: block; padding-top: 24px; margin-top: 18px; border-top: 1px solid var(--rule, #C9D3DF); }
.ds-cancel-button { border: 0; background: transparent; color: var(--blue, #173F8A); text-decoration: underline; text-underline-offset: 4px; padding: 10px 0; min-height: 44px; font: 400 14px/1.6 'Noto Sans TC', sans-serif; cursor: pointer; touch-action: manipulation; }
.ds-cancel-button:hover { text-decoration: underline; }
.ds-cancel-button:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-field { display: grid; gap: 6px; color: var(--secondary, #46546E); font: 400 14px/1.6 'Noto Sans TC', sans-serif; }
.ds-input { border: 1px solid var(--secondary, #46546E); border-radius: 3px; background: var(--white, #fff); color: var(--ink, #14213D); min-height: 44px; padding: 9px 10px; min-width: 0; font: 400 14px/1.6 'Noto Sans TC', sans-serif; caret-color: var(--blue, #173F8A); touch-action: manipulation; }
.ds-input:hover { border-color: var(--secondary, #46546E); }
.ds-input[readonly] { background: var(--ground, #EEF2F6); }
.ds-input:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-rooms { display: flex; gap: 4px; height: 56px; background: var(--blue, #173F8A); font: 400 14px/1.6 'Noto Sans TC', sans-serif; }
.ds-room-link { display: flex; align-items: center; padding: 0 16px; border-bottom: 3px solid transparent; text-decoration: none; font-size: 15px; white-space: nowrap; color: #E4EBF7; touch-action: manipulation; }
.ds-room-link:hover { text-decoration: none; }
.ds-room-link[aria-current="page"] { border-bottom-color: var(--yellow, #F2C230); color: var(--white, #fff); font-weight: 500; }
@media (min-width: 900px) and (max-width: 1170px) { .ds-room-link { padding: 0 10px; } }
@media (max-width: 899px) { .ds-rooms { gap: 0; } .ds-room-link { font-size: 12px; padding: 0 8px; } }
@media (max-width: 420px) { .ds-room-link { font-size: 11px; padding: 0 6px; } }
.ds-room-link:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-keynotes { display: flex; align-items: center; gap: 16px; padding: 8px; }
.ds-keynote { position: relative; width: 36px; height: 36px; border: 1.4px solid var(--ink, #14213D); border-radius: 50%; background: var(--white, #fff); color: var(--ink, #14213D); font: 600 16px 'Barlow Semi Condensed', sans-serif; display: grid; place-items: center; padding: 0; cursor: pointer; touch-action: manipulation; }
.ds-keynote[aria-pressed="true"] { background: var(--ink, #14213D); color: var(--yellow, #F2C230); }
.ds-keynote:hover { background: var(--yellow, #F2C230); color: var(--ink, #14213D); }
@media (max-width: 899px) {
  .ds-keynote { width: 44px; height: 44px; border: 0; background: transparent; isolation: isolate; font-size: 14px; }
  .ds-keynote::before { content: ''; position: absolute; inset: 7px; width: 30px; height: 30px; box-sizing: border-box; border: 1.4px solid var(--ink, #14213D); border-radius: 50%; background: var(--white, #fff); z-index: -1; }
  .ds-keynote[aria-pressed="true"] { background: transparent; color: var(--yellow, #F2C230); }
  .ds-keynote[aria-pressed="true"]::before { background: var(--ink, #14213D); }
  .ds-keynote:hover { background: transparent; color: var(--ink, #14213D); }
  .ds-keynote:hover::before { background: var(--yellow, #F2C230); }
}
.ds-keynote:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-record { background: var(--white, #fff); color: var(--ink, #14213D); padding: 22px 24px; border-bottom: 1px solid var(--rule, #C9D3DF); font: 400 14px/1.6 'Noto Sans TC', sans-serif; }
.ds-record-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; }
.ds-record-title { margin: 0; font-size: 20px; font-weight: 700; text-wrap: balance; }
.ds-record-details { display: flex; gap: 8px 24px; flex-wrap: wrap; margin: 8px 0; color: var(--secondary, #46546E); }
.ds-record-num { font-family: 'Barlow Semi Condensed', 'Noto Sans TC', sans-serif; font-variant-numeric: tabular-nums; }
@media (max-width: 899px) { .ds-record { padding: 20px 16px; } .ds-record-heading { flex-wrap: wrap; gap: 6px; } }

.ds-layer-band { display: flex; justify-content: space-between; color: var(--secondary, #46546E); padding: 14px 0 8px; border-bottom: 1px solid var(--rule, #C9D3DF); background: var(--white, #fff); font: 400 13px/1.6 'Noto Sans TC', sans-serif; }
.ds-layer-code { font-family: 'Barlow Semi Condensed', 'Noto Sans TC', sans-serif; font-variant-numeric: tabular-nums; font-weight: 600; color: var(--ink, #14213D); }
.ds-layer-button { border: 0; background: transparent; color: var(--secondary, #46546E); font: 400 13px/1.6 'Noto Sans TC', sans-serif; padding: 0; min-height: 24px; text-align: left; cursor: pointer; touch-action: manipulation; }
.ds-layer-button:hover, .ds-layer-button[aria-pressed="true"] { color: var(--ink, #14213D); font-weight: 700; }
@media (max-width: 899px) { .ds-layer-button { min-height: 44px; } }
.ds-layer-button:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 3px; box-shadow: 0 0 0 5px var(--ink, #14213D); }

.ds-scan-choice { display: flex; align-items: center; gap: 18px; text-align: left; background: var(--white, #fff); color: var(--ink, #14213D); border: 1px solid var(--rule, #C9D3DF); padding: 22px; min-height: 96px; font: 400 14px/1.6 'Noto Sans TC', sans-serif; cursor: pointer; touch-action: manipulation; }
.ds-scan-choice:hover { background: #E3E9F0; }
.ds-scan-icon { width: 28px; height: 28px; flex-shrink: 0; stroke: var(--ink, #14213D); stroke-width: 1.5; fill: none; }
.ds-scan-title { font-size: 18px; font-weight: 700; display: block; }
.ds-scan-hint { font-size: 14px; color: var(--secondary, #46546E); }
.ds-scan-choice:focus-visible { outline: 2px solid var(--yellow, #F2C230); outline-offset: 2px; box-shadow: 0 0 0 5px var(--ink, #14213D); }
